    );
  },

  getUserBySession(sessionId: string) {
    return query("getUserBySession", () => {
      const userId = sessionId.startsWith(SESSION_PREFIX) ? sessionId.slice(SESSION_PREFIX.length) : "";
      const user = store.users.find((u) => u.id === userId);
